    /// Gate the delivery this pass is about to make on the queue's key, and open the data
    /// keys its messages were sealed under.
    fn prepare_delivery(
        &self,
        store: &Store,
        request: &Request,
        ctx: &smithy_server_runtime::OperationContext<'_>,
        now: SystemTime,
    ) -> Result<(), ReceiveMessageError> {
        // A receive that found messages to hand over and cannot use the key they
        // are sealed under still made a delivery attempt on them: the attempt is
        // counted before the refusal is answered, so a consumer the key does not
        // permit drives those messages to the queue's dead-letter target rather
        // than being refused the same messages for ever. Nothing is handed over
        // and nothing is hidden.
        let authorized = match sqs::encryption::authorize_queue_key(
            &*self.engine,
            ctx,
            &request.queue_url,
            sqs::encryption::DECRYPT_ACTION,
        ) {
            Ok(authorized) => authorized,
            Err(refusal) => {
                let mut state = store.lock();
                if let Some(queue) = state.queue_by_url_mut(&request.region, &request.queue_url) {
                    queue.count_refused_delivery(now, request.max_messages);
                }
                return Err(kms_refusal(refusal));
            }
        };
        // The data keys the messages this receive is about to hand over were sealed
        // under have to be opened before their bodies go over: a data key still
        // inside the queue's `KmsDataKeyReusePeriodSeconds` window is reused as it
        // is, and one past that window is opened by a `kms:Decrypt` call made on
        // the caller's behalf (`sqs::data_keys`). Which messages those are is read
        // under the lock and the lock is then released, so KMS is never asked
        // anything while this service's own guard is held. A queue on the Amazon
        // SQS owned key is sealed under no data key of the account's, so it is not
        // even asked which messages are next.
        if authorized.is_some() {
            let sealed: Vec<sqs::MessageDataKey> = {
                let state = store.lock();
                state
                    .queue_by_url(&request.region, &request.queue_url)
                    .map(|queue| {
                        queue
                            .delivery_order(now, request.max_messages)
                            .into_iter()
                            .filter_map(|index| queue.messages.get(index)?.data_key.clone())
                            .collect()
                    })
                    .unwrap_or_default()
            };
            sqs::data_keys::open_message_data_keys(&*self.engine, ctx, &request.region, &sealed, now);
        }
        Ok(())
    }

    /// One pass over the queue under the lock: authorize the caller, then replay the batch a
    /// retry names or hand over what is deliverable.
    fn take_messages(
        &self,
        store: &Store,
        request: &Request,
        ctx: &smithy_server_runtime::OperationContext<'_>,
        now: SystemTime,
        delivering: bool,
    ) -> Result<Taken, ReceiveMessageError> {
        let mut state = store.lock();
        let Some(queue) = state.queue_by_url_mut(&request.region, &request.queue_url) else {
            return Err(ReceiveMessageErrorModeled::QueueDoesNotExist(
                sqs::queue_does_not_exist(),
            )
            .into());
        };
        // Retention lapses and visibility timeouts are owed by the clock: this
        // materialises what was already due, it does not consume anything. It
        // also forgets the receive attempts whose retry window has run out.
        queue.materialise_due(now);

        // Whether this caller may receive from this queue is decided against the
        // queue's own policy and the caller's identity-based policies, before any
        // message is handed over or made invisible.
        let (queue_arn, policy) = (queue.arn.clone(), queue.policy().map(str::to_string));
        if let Some(denied) = sqs::authorization::denied(
            &*self.engine,
            ctx,
            <Self as smithy_server_runtime::Operation>::NAME,
            &queue_arn,
            policy.as_deref(),
        ) {
            return Err(denied);
        }

        let visibility_timeout = request
            .visibility_timeout
            .map_or_else(|| queue.integer(sqs::VISIBILITY_TIMEOUT), i64::from);
        let wait = sqs::seconds(request.wait_time_seconds.map_or_else(
            || queue.integer(sqs::RECEIVE_MESSAGE_WAIT_TIME_SECONDS),
            i64::from,
        ));
        let invisible_until = sqs::after(now, visibility_timeout);

        // "This parameter applies only to FIFO (first-in-first-out) queues": a
        // standard queue keeps no receive attempts, because nothing there is
        // ordered or deduplicated, so the token names no batch to replay. It is
        // taken and left unused rather than refused: no recorded call shows a
        // standard-queue receive being turned away for carrying it, and the
        // member's own documentation states only which queue type it applies to.
        //
        // `delivering` is what the queue's key was decided for: an iteration that
        // found nothing to hand over hands nothing over, so a batch that arrived
        // since is served by the NEXT poll iteration, which decides the key
        // afresh, rather than by this one, which never asked about the decryption.
        let attempt_id = request
            .attempt_id
            .as_ref()
            .filter(|_| queue.is_fifo() && delivering);

        if let Some((attempt_id, attempt)) = attempt_id.and_then(|given| {
            queue
                .receive_attempts
                .get(given)
                .cloned()
                .map(|attempt| (given, attempt))
        }) {
            let messages = request.replay(queue, attempt_id, attempt, invisible_until, now)?;
            return Ok(Taken::Replayed(messages));
        }
        let messages = request.deliver(queue, attempt_id, delivering, invisible_until, now);
        Ok(Taken::Polled { messages, wait })
    }
}

