                    .queue_by_url(&request.region, &request.queue_url)
                    .map(|queue| {
                        queue
                            .delivery_order(now, request.max_messages)
                            .into_iter()
                            .filter_map(|index| queue.messages.get(index)?.data_key.clone())
                            .collect()
