    async fn handle(
        &self,
        input: Self::Input,
        ctx: &smithy_server_runtime::OperationContext<'_>,
    ) -> Result<Self::Output, Self::Error> {
        // Request metadata this call records: the access key id identifies the caller in
        // the audit record below, the way the real service's trail does.
        let akid = ::emulator_server::extract_akid(&ctx.parts().headers);

        // "The maximum value for messages per second is 500"
        // (StartMessageMoveTaskRequest$MaxNumberOfMessagesPerSecond). A rate of zero or
        // less would move nothing, so a fixed rate is an integer from 1 to that
        // maximum; a request that names none leaves the rate to the service.
        if input
            .max_number_of_messages_per_second
            .is_some_and(|rate| {
                !(sqs::MIN_MESSAGES_PER_SECOND..=sqs::MAX_MESSAGES_PER_SECOND).contains(&rate)
            })
        {
            return Err(Scaffolded::invalid_parameter_value(
                sqs::message_move_rate_out_of_range_message(),
            ));
        }

        // Both ARNs are classified BEFORE the store is reached: a value that names no
        // queue in any account is not an address this service can resolve, which is what
        // the modelled `InvalidAddress` ("The specified ID is invalid.") refuses, while a
        // well-formed ARN of another account, another service or ANOTHER REGION names a
        // resource that simply does not exist here — a task moves messages between two
        // queues of the region the call addressed, so an ARN of another region names no
        // queue this call can reach.
        let region = sqs::request_region(ctx.parts());
        let source_name = match sqs::parse_queue_arn(&input.source_arn, &region) {
            sqs::QueueArn::OfThisRegion(name) => name.to_string(),
            sqs::QueueArn::OfAnotherRegion { .. } | sqs::QueueArn::Elsewhere => {
                return Err(StartMessageMoveTaskErrorModeled::ResourceNotFoundException(
                    sqs::resource_not_found("SourceArn"),
                )
                .into())
            }
            sqs::QueueArn::Malformed => {
                return Err(StartMessageMoveTaskErrorModeled::InvalidAddress(
                    sqs::invalid_address("SourceArn"),
                )
                .into())
            }
        };
        // "The ARN of the queue that receives the moved messages. ... If this field is
        // left blank, the messages will be redriven back to their respective original
        // source queues."
        let named_destination = match input
            .destination_arn
            .as_deref()
            .map(str::trim)
            .filter(|arn| !arn.is_empty())
            .map(|arn| sqs::parse_queue_arn(arn, &region))
        {
            Some(sqs::QueueArn::OfThisRegion(name)) => Some(name.to_string()),
            Some(sqs::QueueArn::OfAnotherRegion { .. }) | Some(sqs::QueueArn::Elsewhere) => {
                return Err(StartMessageMoveTaskErrorModeled::ResourceNotFoundException(
                    sqs::resource_not_found("DestinationArn"),
                )
                .into())
            }
            Some(sqs::QueueArn::Malformed) => {
                return Err(StartMessageMoveTaskErrorModeled::InvalidAddress(
                    sqs::invalid_address("DestinationArn"),
                )
                .into())
            }
            None => None,
        };

        // "Source queue arn and destination queue arn cannot be the same": a task whose
        // destination IS its source would move a queue's messages onto itself, so the pair
        // is refused before any task state is allocated. The two are compared as the queues
        // they RESOLVE to, so a second spelling of the one queue is the same queue here.
        if named_destination
            .as_deref()
            .is_some_and(|name| name == source_name)
        {
            return Err(Scaffolded::invalid_parameter_value(
                sqs::SAME_SOURCE_AND_DESTINATION,
            ));
        }

        let store = sqs::service_state(&*self.engine).ok_or_else(|| {
            StartMessageMoveTaskErrorModeled::UnsupportedOperation(sqs::store_unavailable())
        })?;
        let mut state = store.lock();

        let now = SystemTime::now();
        // Retention lapses and visibility timeouts are owed by the clock, not by this
        // call: what the task may take is what the source queue can hand out once
        // everything already due has been applied.
        state.materialise_due(now);

        if !state.holds_queue(&region, &source_name) {
            return Err(StartMessageMoveTaskErrorModeled::ResourceNotFoundException(
                sqs::resource_not_found("SourceArn"),
            )
            .into());
        }

        // Whether this caller may move the source queue's messages is decided against
        // that queue's own policy and the caller's identity-based policies, before any
        // task is recorded.
        let (queue_arn, policy) = {
            let queue = state
                .queue(&region, &source_name)
                .expect("the queue was resolved out of this same store");
            (queue.arn.clone(), queue.policy().map(str::to_string))
        };
        if let Some(denied) = sqs::authorization::denied(
            &*self.engine,
            ctx,
            Self::NAME,
            &queue_arn,
            policy.as_deref(),
        ) {
            return Err(denied);
        }

        // "This action is currently limited to supporting message redrive from queues
        // that are configured as dead-letter queues (DLQs) of other Amazon SQS queues
        // only": the source queue is a DLQ exactly when another queue's RedrivePolicy
        // names it as its dead-letter target. The queue the caller NAMED is what does
        // not satisfy the rule, so the fault is in that parameter's value, and the
        // refusal states that pre-condition in its own sentence rather than borrowing
        // the documentation sentence of the `UnsupportedOperation` class above.
        let dead_letter_sources = state.dead_letter_source_queue_names(&region, &source_name);
        if dead_letter_sources.is_empty() {
            return Err(Scaffolded::invalid_parameter_value(
                sqs::DEAD_LETTER_SOURCE_REQUIRED,
            ));
        }

        // With no destination named, the messages go back to the queue that drives its
        // messages here. This store records no per-message origin, so the respective
        // original source queue is determined exactly when the dead-letter queue has a
        // single source queue; with several of them the task cannot say which queue a
        // given message came from, so the call is refused rather than guessing one.
        // Whether the request SPECIFIED the destination is part of the task's record: a
        // reader reports `DestinationArn` for a task whose request named one and NULL for
        // one that left the field blank, whichever queue this call resolved the messages
        // back to.
        let destination_specified = named_destination.is_some();
        let destination_name = match named_destination {
            Some(name) if state.holds_queue(&region, &name) => name,
            Some(_) => {
                return Err(StartMessageMoveTaskErrorModeled::ResourceNotFoundException(
                    sqs::resource_not_found("DestinationArn"),
                )
                .into())
            }
            None if dead_letter_sources.len() == 1 => dead_letter_sources[0].clone(),
            None => {
                return Err(StartMessageMoveTaskErrorModeled::UnsupportedOperation(
                    UnsupportedOperation {
                        message: Some(format!(
                            "The source queue is the dead-letter queue of {} queues, so the \
                             original source queue of each message is not determined: name the \
                             queue to move the messages to in DestinationArn.",
                            dead_letter_sources.len()
                        )),
                    },
                )
                .into())
            }
        };
        // The pair the task would run over has to be two queues, whether the request named
        // the destination or left it to the queue that drives its messages here: a queue
        // whose own `RedrivePolicy` names itself is its own dead-letter source, so the
        // blank-destination form can resolve to the source queue too, and moving a queue's
        // messages onto itself is the same degenerate move.
        if destination_name == source_name {
            return Err(Scaffolded::invalid_parameter_value(
                sqs::SAME_SOURCE_AND_DESTINATION,
